package com.ruoyi.majorpilot.classifier;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.ruoyi.majorpilot.content.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class FrozenClassifierTest {
    private static final ObjectMapper JSON=new ObjectMapper();
    private JsonNode asset(String key)throws Exception {return JSON.readTree(FrozenClassifierTest.class.getClassLoader().getResourceAsStream("task-content/ai-support/1.0.0/"+key+".json"));}
    private JsonNode toy(){ObjectNode m=JSON.createObjectNode();List<String> v=List.of("ab","cd","ef","gh");m.set("vocabulary",JSON.valueToTree(v));ObjectNode counts=m.putObject("baseCounts"),config=m.putObject("baselineConfig"),ids=config.putObject("definitionVariantIds");ArrayNode variants=m.putArray("definitionVariants");for(int i=0;i<4;i++){String label=FrozenClassifier.LABELS.get(i);ObjectNode row=counts.putObject(label);for(int j=0;j<4;j++)row.put(v.get(j),i==j?3:1);ids.put(label,"default-"+i);variants.addObject().put("id","default-"+i).put("label",label).putArray("features");}config.putArray("exampleIds");config.put("confidenceThreshold",0.4).put("lowConfidencePolicy","MANUAL_REVIEW");m.putArray("examples").addObject().put("exampleId","add-t").put("messageText","ab ab").put("goldLabel",FrozenClassifier.LABELS.getFirst());return m;}
    @Test void unicodeAndNegativeHalfUp(){assertEquals(Map.of("ab",1,"bc",1),FrozenClassifier.features("Ａ， Ｂ\u00a0C"));assertEquals(Map.of("😀a",1,"ab",1),FrozenClassifier.features("😀ab"));assertEquals(-1.234568,FrozenClassifier.halfUp6(-1.2345675));assertEquals(1.234568,FrozenClassifier.halfUp6(1.2345675));}
    @Test void exactTieThresholdAndRoundedScoreSoftmax(){JsonNode m=toy(),c=m.path("baselineConfig");JsonNode missing=FrozenClassifier.predict(m,c,"OOV");assertEquals(0.25,missing.path("confidence").asDouble());assertEquals("MANUAL_REVIEW",missing.path("routedLabel").asText());assertEquals("technical_issue",FrozenClassifier.predict(m,c,"ab").path("routedLabel").asText());assertEquals(0.4,FrozenClassifier.predict(m,c,"ab").path("confidence").asDouble());assertEquals(0.571428,FrozenClassifier.predict(m,c,"ab ab").path("confidence").asDouble());assertEquals("technical_issue",FrozenClassifier.predict(m,c,"ab cd").path("predictedLabel").asText());((ObjectNode)c).putArray("exampleIds").add("add-t");assertEquals(0.454545,FrozenClassifier.predict(m,c,"ab").path("confidence").asDouble());((ObjectNode)c).putArray("exampleIds");((ArrayNode)m.at("/definitionVariants/0/features")).add("ab");assertEquals(0.431034,FrozenClassifier.predict(m,c,"ab").path("confidence").asDouble());}
    @Test void denominatorAndNullAreNeverFabricated(){JsonNode r=FrozenClassifier.metrics(FrozenClassifier.LABELS,List.of("technical_issue","concept_confusion","technical_issue","MANUAL_REVIEW"));assertEquals(0.75,r.path("coverage").asDouble());assertEquals(0.666667,r.path("autoAccuracy").asDouble());assertEquals(0.5,r.path("totalCorrectAutoRate").asDouble());assertTrue(r.at("/perLabel/3/precision").isNull());assertEquals(0,r.at("/perLabel/3/recall").asDouble());assertTrue(FrozenClassifier.metrics(FrozenClassifier.LABELS,Collections.nCopies(4,"MANUAL_REVIEW")).path("autoAccuracy").isNull());}
    @Test void allJavaResultsMatchCommittedJavascriptGoldens()throws Exception {JsonNode m=asset("classifier-model"),g=asset("golden-private"),samples=asset("evaluation-private");assertTrue(ClassifierAssets.equivalent(g.path("baseline"),FrozenClassifier.compare(m,g.path("baselineConfig"),samples)));assertTrue(ClassifierAssets.equivalent(g.path("changed"),FrozenClassifier.compare(m,g.path("changedConfig"),samples)));for(JsonNode sample:asset("practice-public"))assertTrue(ClassifierAssets.equivalent(sample.path("baseline"),FrozenClassifier.predict(m,m.path("baselineConfig"),sample.path("messageText").asText())));}
    @Test void catalogValidationAndPublicProjectionRetainReleaseBoundary(){var repository=new TaskContentRepository(JSON);var bundle=repository.get("ai-support/1.0.0/manifest.json");JsonNode m=bundle.manifest();TaskManifestValidator.validate(m);var version=new TaskContent.Version(1,m.path("taskVersionId").asText(),"MAJOR","AI",null,"1.0.0",bundle.manifestSha256(),m);String visible=TaskContentViews.publicManifest(version).toString();for(String secret:List.of("evaluation-private","support-messages","training-private","golden-private","review-private","privateAssetKeys","modelAssetKey","datasetAssetKey"))assertFalse(visible.contains(secret),secret);assertThrows(RuntimeException.class,()->repository.asset(bundle,"evaluation-private",true));var engine=new ClassifierEngine(repository,JSON);assertTrue(engine.isBaseline(version,m.path("operations").get(0),readBaseline(repository,bundle)));}
    private JsonNode readBaseline(TaskContentRepository r,TaskContentRepository.Bundle b){try{return JSON.readTree(r.asset(b,"classifier-model",true)).path("baselineConfig");}catch(Exception e){throw new IllegalStateException(e);}}
    @Test void nullableNumbersOnlySupportedByV2SchemaValidation()throws Exception {JsonNode schema=JSON.readTree("{\"type\":[\"number\",\"null\"],\"minimum\":0,\"maximum\":1}");assertThrows(RuntimeException.class,()->TaskInputValidator.validateSchema(schema));assertDoesNotThrow(()->TaskInputValidator.validateSchema(schema,true));assertDoesNotThrow(()->TaskInputValidator.validate(schema,NullNode.instance,true));assertThrows(RuntimeException.class,()->TaskInputValidator.validate(schema,TextNode.valueOf("0.5"),true));}
    @Test void nullableTypeDoesNotBypassExplicitEnumOrConstant()throws Exception {JsonNode schema=JSON.readTree("{\"type\":[\"number\",\"null\"],\"enum\":[0.5]}");assertDoesNotThrow(()->TaskInputValidator.validateSchema(schema,true));assertThrows(RuntimeException.class,()->TaskInputValidator.validate(schema,NullNode.instance,true));}
}
